UPDATE landing_pages SET name = 'Northstar workspace access', html = '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#eef1f6;color:#172033;font-family:Segoe UI,Arial,sans-serif}.card{width:min(440px,calc(100% - 32px));background:#fff;padding:46px 42px 34px;box-shadow:0 18px 45px #1d2c4930}.mark{display:grid;grid-template-columns:repeat(4,12px);gap:3px;width:max-content}.mark i{height:12px;background:#ed6a5e}.mark i:nth-child(2){background:#f4bf4f}.mark i:nth-child(3){background:#4f9d69}.mark i:nth-child(4){background:#3779c4}.eyebrow{margin:31px 0 8px;color:#5d6880;font-size:13px}h1{font-size:25px;margin:0 0 8px}.field{border-bottom:1px solid #6b7690;padding:15px 2px;color:#8993a6;font-size:15px}.go{float:right;margin-top:28px;border:0;background:#215fbc;color:#fff;padding:11px 25px;font-weight:600}.notice{clear:both;padding-top:36px;font-size:11px;color:#748099;border-top:2px solid #ed6a5e;margin-top:36px}</style></head><body><main class="card"><div class="mark"><i></i><i></i><i></i><i></i></div><p class="eyebrow">Northstar identity</p><h1>Welcome back</h1><div class="field">Work email</div><button class="go" id="sim-submit">Continue</button><p class="notice">Security awareness simulation. Do not enter personal information.</p></main><script>document.getElementById("sim-submit").onclick=function(){var t="{{TOKEN}}";fetch("/api/v1/tracking/"+t+"/submit",{method:"POST"}).then(function(){location.href="/training/{{SLUG}}?token="+t})}</script></body></html>', updated_at = NOW() WHERE slug = 'm365-login';

UPDATE landing_pages SET name = 'Orbit account access', html = '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#fff;color:#1f2937;font-family:Arial,sans-serif}.card{width:min(450px,calc(100% - 32px));border:1px solid #d5dce8;border-radius:18px;padding:42px}.orbit{width:62px;height:62px;border:8px solid #2563eb;border-left-color:#f97316;border-radius:50%;margin:auto}.brand{text-align:center;font-size:19px;font-weight:700;margin:16px}h1{text-align:center;font-size:24px;margin:28px 0 8px}.sub{text-align:center;color:#65738b;font-size:14px;margin-bottom:30px}.field{border:1px solid #b9c4d6;border-radius:8px;padding:15px;color:#7b879b}.actions{display:flex;justify-content:space-between;align-items:center;margin-top:26px}.help{color:#2563eb;font-size:13px}.go{border:0;border-radius:7px;background:#2563eb;color:#fff;padding:11px 22px;font-weight:700}.notice{margin-top:34px;padding-top:12px;border-top:2px solid #f97316;color:#758198;font-size:11px}</style></head><body><main class="card"><div class="orbit"></div><div class="brand">orbit</div><h1>Sign in</h1><p class="sub">Use your organization account</p><div class="field">Email address</div><div class="actions"><span class="help">Need help?</span><button class="go" id="sim-submit">Next</button></div><p class="notice">Simulation environment. Credentials are never requested or stored.</p></main><script>document.getElementById("sim-submit").onclick=function(){var t="{{TOKEN}}";fetch("/api/v1/tracking/"+t+"/submit",{method:"POST"}).then(function(){location.href="/training/{{SLUG}}?token="+t})}</script></body></html>', updated_at = NOW() WHERE slug = 'google-login';

UPDATE landing_pages SET name = 'Helio console access', html = '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#101415;color:#ecf3ee;font-family:Arial,sans-serif}.card{width:min(410px,calc(100% - 32px));padding:40px;border:1px solid #33423b;border-radius:18px;background:#171c1a;box-shadow:0 25px 70px #0008}.glyph{width:42px;height:42px;margin:auto;border:3px solid #6ce0a0;border-radius:14px;transform:rotate(45deg)}.glyph:after{content:"";display:block;width:14px;height:14px;margin:11px;background:#6ce0a0;border-radius:4px}h1{text-align:center;font-size:23px;margin:28px 0 8px}.sub{text-align:center;color:#a8b9ae;font-size:14px;margin-bottom:28px}.field{background:#222a26;border:1px solid #43544a;border-radius:8px;padding:14px;color:#84958b}.go{width:100%;margin-top:16px;border:0;border-radius:8px;background:#42b775;color:#062e1c;padding:13px;font-weight:800}.notice{margin-top:27px;border-left:2px solid #6ce0a0;padding-left:10px;color:#9eb4a7;font-size:11px}</style></head><body><main class="card"><div class="glyph"></div><h1>Continue to Helio</h1><p class="sub">One place for your team tools.</p><div class="field">Email address</div><button class="go" id="sim-submit">Continue</button><p class="notice">Awareness simulation. No account data is collected.</p></main><script>document.getElementById("sim-submit").onclick=function(){var t="{{TOKEN}}";fetch("/api/v1/tracking/"+t+"/submit",{method:"POST"}).then(function(){location.href="/training/{{SLUG}}?token="+t})}</script></body></html>', updated_at = NOW() WHERE slug = 'chatgpt-login';

UPDATE landing_pages SET name = 'Prisma studio invitation', html = '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#e8c9ff,#bdf6f3);font-family:Trebuchet MS,Arial,sans-serif;color:#251d3c}.card{width:min(440px,calc(100% - 32px));background:#fff;border-radius:26px;padding:42px;box-shadow:0 26px 55px #5a258638}.brand{font-size:30px;font-weight:800;letter-spacing:-2px;background:linear-gradient(90deg,#a62df5,#00aeb7);color:transparent;background-clip:text}h1{font-size:25px;margin:34px 0 8px}.sub{color:#665d78;line-height:1.45;font-size:14px}.field{margin-top:24px;border:2px solid #d9cee8;border-radius:12px;padding:14px;color:#91869f}.go{margin-top:13px;width:100%;border:0;border-radius:12px;background:linear-gradient(90deg,#9b36ed,#0bbbc2);padding:13px;color:#fff;font-weight:800}.notice{margin-top:25px;color:#7d718b;font-size:11px;text-align:center}</style></head><body><main class="card"><div class="brand">prisma</div><h1>Join your design space</h1><p class="sub">Your invitation is ready. Continue with your work email to view the shared workspace.</p><div class="field">name@company.com</div><button class="go" id="sim-submit">Continue with email</button><p class="notice">Simulation only - never use a real password here.</p></main><script>document.getElementById("sim-submit").onclick=function(){var t="{{TOKEN}}";fetch("/api/v1/tracking/"+t+"/submit",{method:"POST"}).then(function(){location.href="/training/{{SLUG}}?token="+t})}</script></body></html>', updated_at = NOW() WHERE slug = 'canva-login';

UPDATE landing_pages SET name = 'Fieldnote professional network', html = '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:linear-gradient(120deg,#cfd8df,#eff2f3 45%,#c5d0d5);font-family:Arial,sans-serif;color:#182431}.card{width:min(390px,calc(100% - 32px));background:#fff;padding:30px;border-radius:8px;box-shadow:0 10px 34px #20334436}.brand{font-size:25px;font-weight:800;color:#174f77}.brand b{display:inline-grid;place-items:center;background:#174f77;color:#fff;border-radius:3px;font-size:17px;width:21px;height:21px}h1{font-size:25px;margin:26px 0 20px}.field{border:1px solid #8794a0;border-radius:4px;padding:13px;color:#667786;margin-bottom:12px}.go{width:100%;border:0;border-radius:22px;background:#174f77;color:#fff;padding:12px;font-weight:700}.terms{font-size:11px;text-align:center;line-height:1.4;color:#667786;margin:20px 8px}.notice{font-size:11px;border-top:2px solid #e27835;padding-top:10px;color:#64717e}</style></head><body><main class="card"><div class="brand">field<b>f</b>note</div><h1>Stay connected</h1><div class="field">Email or member ID</div><button class="go" id="sim-submit">Agree and continue</button><p class="terms">By continuing, you acknowledge the community terms.</p><p class="notice">This is a security training simulation.</p></main><script>document.getElementById("sim-submit").onclick=function(){var t="{{TOKEN}}";fetch("/api/v1/tracking/"+t+"/submit",{method:"POST"}).then(function(){location.href="/training/{{SLUG}}?token="+t})}</script></body></html>', updated_at = NOW() WHERE slug = 'linkedin-login';

UPDATE landing_pages SET name = 'Canvas social access', html = '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#fafafa;font-family:Arial,sans-serif;color:#222}.card{width:min(350px,calc(100% - 32px));background:#fff;border:1px solid #dedede;padding:38px 34px}.logo{margin:auto;width:54px;height:54px;border-radius:17px;background:radial-gradient(circle at 31% 76%,#ffd15b 0 7%,transparent 8%),linear-gradient(35deg,#e44164,#7d38bd 58%,#ea9e45);position:relative}.logo:after{content:"";position:absolute;inset:13px;border:3px solid #fff;border-radius:12px}.word{text-align:center;font-family:Georgia,serif;font-size:29px;margin:16px 0 30px}.field{border:1px solid #ddd;background:#fafafa;border-radius:4px;padding:12px;color:#9a9a9a;font-size:12px;margin:8px 0}.go{width:100%;border:0;border-radius:5px;background:#287fe5;color:#fff;padding:10px;font-weight:700;margin-top:8px}.notice{text-align:center;font-size:10px;color:#8b8b8b;border-top:2px solid #e44164;padding-top:12px;margin-top:24px}</style></head><body><main class="card"><div class="logo"></div><div class="word">Canvas</div><div class="field">Mobile number or username</div><div class="field">Password</div><button class="go" id="sim-submit">Log in</button><p class="notice">Simulated training screen. Inputs are decorative.</p></main><script>document.getElementById("sim-submit").onclick=function(){var t="{{TOKEN}}";fetch("/api/v1/tracking/"+t+"/submit",{method:"POST"}).then(function(){location.href="/training/{{SLUG}}?token="+t})}</script></body></html>', updated_at = NOW() WHERE slug = 'instagram-login';

UPDATE landing_pages SET name = 'Harbor community access', html = '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#edf2f7;font-family:Arial,sans-serif;color:#1b2733}.wrap{width:min(920px,calc(100% - 32px));display:grid;grid-template-columns:1fr 380px;gap:48px;align-items:center}.hero{color:#2468c0;font-size:55px;font-weight:800;letter-spacing:-3px}.tag{font-size:23px;color:#27364a;max-width:390px}.card{background:#fff;padding:22px;border-radius:10px;box-shadow:0 4px 16px #29486e22}.field{border:1px solid #ccd5df;border-radius:7px;padding:13px;color:#8b96a4;margin-bottom:10px}.go{width:100%;border:0;border-radius:7px;background:#2468c0;color:#fff;padding:12px;font-size:16px;font-weight:700}.notice{font-size:11px;color:#748092;border-top:2px solid #e17e38;padding-top:12px;margin-top:18px}@media(max-width:720px){.wrap{grid-template-columns:1fr;gap:24px}.hero{text-align:center;font-size:45px}.tag{margin:auto;text-align:center}}</style></head><body><main class="wrap"><section><div class="hero">harbor</div><p class="tag">A calm place for your communities and conversations.</p></section><section class="card"><div class="field">Email or phone</div><div class="field">Password</div><button class="go" id="sim-submit">Log in</button><p class="notice">Security awareness simulation. No information is submitted.</p></section></main><script>document.getElementById("sim-submit").onclick=function(){var t="{{TOKEN}}";fetch("/api/v1/tracking/"+t+"/submit",{method:"POST"}).then(function(){location.href="/training/{{SLUG}}?token="+t})}</script></body></html>', updated_at = NOW() WHERE slug = 'facebook-login';

UPDATE landing_pages SET name = 'Aster identity gateway', html = '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f2f4f7;color:#293241;font-family:Arial,sans-serif}.card{width:min(410px,calc(100% - 32px));background:#fff;padding:40px;border:1px solid #d6dde7;border-radius:6px;box-shadow:0 8px 22px #21364b17}.brand{display:flex;align-items:center;gap:10px;font-size:20px;font-weight:700}.star{width:27px;height:27px;background:#ef7e4d;clip-path:polygon(50% 0,61% 36%,100% 50%,61% 64%,50% 100%,39% 64%,0 50%,39% 36%)}h1{font-size:21px;margin:34px 0 8px}.sub{color:#718096;font-size:14px}.field{margin-top:23px;border:1px solid #aeb9c7;border-radius:4px;padding:14px;color:#7f8b9b}.go{margin-top:15px;width:100%;border:0;border-radius:4px;background:#2b638f;color:#fff;padding:12px;font-weight:700}.notice{margin-top:28px;color:#7a8797;font-size:11px;border-left:2px solid #ef7e4d;padding-left:9px}</style></head><body><main class="card"><div class="brand"><span class="star"></span>Aster</div><h1>Sign in to your organization</h1><p class="sub">Use your assigned email to continue.</p><div class="field">Email</div><button class="go" id="sim-submit">Sign in</button><p class="notice">Training simulation. No password field is connected.</p></main><script>document.getElementById("sim-submit").onclick=function(){var t="{{TOKEN}}";fetch("/api/v1/tracking/"+t+"/submit",{method:"POST"}).then(function(){location.href="/training/{{SLUG}}?token="+t})}</script></body></html>', updated_at = NOW() WHERE slug = 'okta-login';

UPDATE landing_pages SET name = 'Relay team workspace', html = '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#fff9f4;color:#30233a;font-family:Arial,sans-serif}.top{height:8px;background:linear-gradient(90deg,#4c2855 25%,#d45d65 25% 50%,#e6bb62 50% 75%,#2ba8a2 75%)}.card{width:min(460px,calc(100% - 32px));margin:10vh auto;background:#fff;padding:42px;border:1px solid #e6ddd7;border-radius:12px}.brand{font-weight:900;font-size:25px;letter-spacing:-1px}.mark{display:inline-grid;grid-template-columns:repeat(2,9px);gap:2px;margin-right:8px}.mark i{width:9px;height:9px;background:#4c2855}.mark i:nth-child(2){background:#d45d65}.mark i:nth-child(3){background:#e6bb62}.mark i:nth-child(4){background:#2ba8a2}h1{font-size:28px;margin:35px 0 10px}.sub{color:#756a7c;font-size:14px}.google{width:100%;margin:25px 0 14px;border:1px solid #bdb5bf;background:#fff;border-radius:6px;padding:12px;color:#423649;font-weight:700}.field{border:1px solid #bdb5bf;border-radius:6px;padding:14px;color:#8d8292}.go{margin-top:14px;width:100%;border:0;border-radius:6px;background:#4c2855;color:#fff;padding:13px;font-weight:700}.notice{font-size:11px;color:#806d7b;border-top:2px solid #2ba8a2;margin-top:28px;padding-top:10px}</style></head><body><div class="top"></div><main class="card"><div class="brand"><span class="mark"><i></i><i></i><i></i><i></i></span>relay</div><h1>Sign in to your workspace</h1><p class="sub">Enter your work email to get started.</p><button class="google" id="sim-submit">Continue with a provider</button><div class="field">you@company.com</div><button class="go" id="sim-submit-alt">Continue with email</button><p class="notice">Simulation only. No credentials are processed.</p></main><script>function go(){var t="{{TOKEN}}";fetch("/api/v1/tracking/"+t+"/submit",{method:"POST"}).then(function(){location.href="/training/{{SLUG}}?token="+t})}document.getElementById("sim-submit").onclick=go;document.getElementById("sim-submit-alt").onclick=go;</script></body></html>', updated_at = NOW() WHERE slug = 'slack-login';

UPDATE landing_pages SET name = 'Crestline account access', html = '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#e8edf2;font-family:Arial,sans-serif;color:#13283d}.top{height:70px;background:#153e63;display:flex;align-items:center;padding:0 max(24px,8vw);color:#fff}.brand{font-size:23px;font-weight:800}.brand span{color:#63c2bb}.shell{width:min(950px,calc(100% - 32px));margin:56px auto;display:grid;grid-template-columns:1fr 390px;background:#fff;box-shadow:0 15px 40px #17334a2b}.story{padding:50px;background:linear-gradient(160deg,#eef5f8,#d7e8eb)}.story h1{font-size:34px;margin:0 0 12px}.story p{color:#456176;line-height:1.55}.card{padding:40px}.card h2{margin:0 0 25px;font-size:21px}.field{border:1px solid #b7c3cf;border-radius:3px;padding:13px;color:#77889a;margin:11px 0}.go{width:100%;margin-top:11px;border:0;border-radius:3px;background:#16867f;color:#fff;padding:13px;font-weight:700}.notice{margin-top:26px;border-top:2px solid #16867f;padding-top:10px;font-size:11px;color:#718497}@media(max-width:720px){.shell{grid-template-columns:1fr;margin:24px auto}.story{display:none}}</style></head><body><header class="top"><div class="brand">crest<span>line</span></div></header><main class="shell"><section class="story"><h1>Your finances, in focus.</h1><p>Review your account activity from one secure place.</p></section><section class="card"><h2>Secure account access</h2><div class="field">Customer ID</div><div class="field">Access key</div><button class="go" id="sim-submit">Enter account</button><p class="notice">Awareness simulation. These controls never transmit data.</p></section></main><script>document.getElementById("sim-submit").onclick=function(){var t="{{TOKEN}}";fetch("/api/v1/tracking/"+t+"/submit",{method:"POST"}).then(function(){location.href="/training/{{SLUG}}?token="+t})}</script></body></html>', updated_at = NOW() WHERE slug = 'banca-login';

INSERT INTO landing_pages (name, slug, category, difficulty, html, active, created_at, updated_at)
SELECT 'Keystone internal portal', 'keystone-internal', 'ACCOUNT', 'MEDIUM', '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#15212b;color:#eaf1f4;font-family:Arial,sans-serif}.frame{width:min(920px,calc(100% - 32px));display:grid;grid-template-columns:42% 58%;min-height:500px;border:1px solid #38505d}.intro{padding:48px;background:#1d313d}.monogram{font-weight:900;font-size:35px;color:#ffb85c}.intro h1{font-size:31px;margin:48px 0 12px}.intro p{color:#aec0c9;line-height:1.5}.form{padding:70px;background:#f7fafb;color:#182d3b}.form h2{margin:0 0 8px;font-size:25px}.form p{color:#647985}.field{border-bottom:1px solid #aebfc8;padding:15px 2px;margin-top:27px;color:#7f919b}.go{margin-top:27px;border:0;background:#d35c44;color:#fff;padding:13px 26px;font-weight:800}.notice{margin-top:46px;border-top:2px solid #ffb85c;padding-top:10px;color:#657986;font-size:11px}@media(max-width:680px){.frame{grid-template-columns:1fr}.intro{padding:30px}.intro h1{margin:20px 0}.form{padding:35px}}</style></head><body><main class="frame"><section class="intro"><div class="monogram">K/</div><h1>Keystone operations</h1><p>One internal gateway for approved teams and service tools.</p></section><section class="form"><h2>Verify your work identity</h2><p>Continue with your assigned organization address.</p><div class="field">Work email</div><button class="go" id="sim-submit">Continue</button><p class="notice">Internal security awareness simulation. No credentials are collected.</p></section></main><script>document.getElementById("sim-submit").onclick=function(){var t="{{TOKEN}}";fetch("/api/v1/tracking/"+t+"/submit",{method:"POST"}).then(function(){location.href="/training/{{SLUG}}?token="+t})}</script></body></html>', 1, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM landing_pages WHERE slug = 'keystone-internal');
